/**
 * Pure TypeScript interface definitions for Vercel global config types.
 *
 * These interfaces serve as the source of truth for types.
 * Zod schemas are generated from these using ts-to-zod.
 */
export interface TelemetryConfig {
    enabled?: boolean;
}
export interface GuidanceConfig {
    enabled?: boolean;
}
export interface UpdatesConfig {
    auto?: boolean;
    /** Allow CLI upgrades to override package-manager minimum release age. */
    bypassMinReleaseAge?: boolean;
}
export type CredStorage = 'auto' | 'file' | 'keyring';
export type CredentialsStorageLocation = Exclude<CredStorage, 'auto'>;
export declare const CRED_STORAGE_CONFIG_VALUES: readonly ["auto", "file", "keyring"];
export declare const CRED_STORAGE_VALUES: ("file" | "keyring")[];
export declare const DEFAULT_CRED_STORAGE: CredentialsStorageLocation;
/** The public half of a DPoP key (RFC 9449), a P-256 key as a JWK. */
export interface DpopPublicKey {
    kty: 'EC';
    crv: 'P-256';
    x: string;
    y: string;
}
/**
 * The key a DPoP login signs its proofs with: its public half, and one of
 * - `d`: a software key, saved with the login.
 * - `sealed`: `d` sealed by a key in this device's chip, which is the only
 *   thing that can unseal it. With `secureEnclave`, that key as wrapped by
 *   this Mac's Secure Enclave; with `tpm`, the name of that key in this PC's
 *   TPM; with `tpmPublic` (Linux), `sealed` is the private area of a TPM
 *   sealed object holding `d`, and `tpmPublic` its public area.
 */
export type DpopPrivateKey = DpopPublicKey & ({
    d: string;
} | {
    secureEnclave: string;
    sealed: string;
} | {
    tpm: string;
    sealed: string;
} | {
    tpmPublic: string;
    sealed: string;
});
export interface AuthConfig {
    '// Note'?: string;
    '// Docs'?: string;
    skipWrite?: boolean;
    token?: string;
    userId?: string;
    /** The last looked-up user's name, with the id it belongs to, for `whoami --cached`. */
    cachedUser?: {
        id: string;
        username: string;
    };
    refreshToken?: string;
    expiresAt?: number;
    tokenSource?: 'flag' | 'env';
    /**
     * Set on a DPoP login, whose tokens are bound to `key`. A DPoP login is
     * saved apart from `auth.json` (see `getDpopAuthConfigFilePath`).
     */
    dpop?: {
        key: DpopPrivateKey;
    };
}
export type AuthFileConfig = Omit<AuthConfig, 'tokenSource'>;
export interface GlobalConfig {
    '// Note'?: string;
    '// Docs'?: string;
    credStorage?: CredStorage;
    currentTeam?: string;
    api?: string;
    telemetry?: TelemetryConfig;
    guidance?: GuidanceConfig;
    updates?: UpdatesConfig;
    /** `false` opts out of the native CLI. Honored for one more release. */
    useNativeBinary?: boolean;
    /** Ignored. Older releases chose the native CLI with it. */
    nativeBinaryAutoOptIn?: boolean;
    /**
     * `false` in a config the CLI created for a first-time user, until their
     * first successful interactive run. Configs from earlier releases don't set
     * it and count as used.
     */
    usedBefore?: boolean;
    /** A first-sign-in welcome was displayed before a successful login. */
    loginWelcomeSeen?: boolean;
    /** First-sign-in next steps were displayed after credentials were saved. */
    loginIntroductionSeen?: boolean;
}
